INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('4820b60f-2c22-5c89-805f-32218791a8a0', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 7, 7, 'A child on a swing is pulled back and released, and then left to swing on her own. What kind of oscillation is this?', NULL, 1, 'multiple_choice'::answer_type, 'A free oscillation at the natural frequency of the swing', NULL, false, NULL, false, NULL, 'Once released with no further push, the swing oscillates at its own natural frequency: a free oscillation. Mark scheme (1 mark). B1: C (A free oscillation at the natural frequency of the swing).', 1, NULL, NULL),
('e0732104-4228-5713-a7bd-e734b2df4e69', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 8, 8, 'A loudspeaker cone is made to vibrate by an alternating current from a signal generator. What kind of oscillation does the cone perform?', NULL, 1, 'multiple_choice'::answer_type, 'A forced oscillation at the frequency of the signal', NULL, false, NULL, false, NULL, 'A periodic driving force from the coil forces the cone to vibrate at the driving (signal) frequency. Mark scheme (1 mark). B1: A (A forced oscillation at the frequency of the signal).', 1, NULL, NULL),
('4833c4fc-3ccb-53ad-9e7d-2fc89c1d2b1e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 9, 9, 'What is meant by the natural frequency of an oscillating system?', NULL, 1, 'multiple_choice'::answer_type, 'The frequency at which it oscillates when displaced and then left to oscillate freely', NULL, false, NULL, false, NULL, 'Natural frequency is the frequency of free oscillations, fixed by the system itself (for example its mass and stiffness). Mark scheme (1 mark). B1: D (The frequency at which it oscillates when displaced and then left to oscillate freely).', 1, NULL, NULL),
('4050c62d-c61b-5d26-bff3-59d31175c284', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 10, 10, 'An oscillator is driven by a periodic force. Once the motion is steady, at what frequency does it oscillate?', NULL, 1, 'multiple_choice'::answer_type, 'The driving frequency', NULL, false, NULL, false, NULL, 'In steady forced oscillation the system moves at the frequency of the driver, whatever its natural frequency. Mark scheme (1 mark). B1: B (The driving frequency).', 1, NULL, NULL),
('b78b1e90-cd48-5c0b-843c-2cc8b89eed29', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 11, 11, 'A 0.40 kg mass hangs on a spring of spring constant 25 N m⁻¹. Calculate the period of its free vertical oscillations.', NULL, 1, 'numeric'::answer_type, '0.7948', 's', false, NULL, false, NULL, 'T = 2π√(m/k) = 2π × √(0.40 ÷ 25) = 0.795 s. Mark scheme (2 marks). C1: T = 2π√(m/k). A1: T = 0.795 s.', 2, NULL, NULL),
('cc70209c-3b43-5d38-b7c1-e977cfb20506', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 12, 12, 'A simple pendulum has length 0.90 m. Calculate the period of its free oscillations. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '1.903', 's', false, NULL, false, NULL, 'T = 2π√(L/g) = 2π × √(0.90 ÷ 9.81) = 1.90 s. Mark scheme (2 marks). C1: T = 2π√(L/g). A1: T = 1.90 s.', 2, NULL, NULL),
('b021d3b6-347c-5c88-9469-3c2982af2c96', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 13, 13, 'A 1.2 kg trolley is held between two springs with a combined spring constant of 300 N m⁻¹. Calculate the natural frequency of its oscillations.', NULL, 1, 'numeric'::answer_type, '2.516', 'Hz', false, NULL, false, NULL, 'f = 1/T = 1 ÷ (2π√(m/k)) = 1 ÷ (2π × √(1.2 ÷ 300)) = 2.52 Hz. Mark scheme (2 marks). C1: f = (1/2π)√(k/m). A1: f = 2.52 Hz.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg3c9fc540-t fg3c9fc540-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3c9fc540-t">Trolley between springs</title><desc id="fg3c9fc540-d">A 1.2 kg trolley on a horizontal track held between two springs fixed to walls; together the springs have a spring constant of 300 N m⁻¹.</desc><rect x="20" y="50" width="10" height="80" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><rect x="390" y="50" width="10" height="80" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="130" x2="400" y2="130" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="170" y="80" width="80" height="40" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="188" cy="124" r="6" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="232" cy="124" r="6" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="30,100 40,100 47.5,108 55,92 62.5,108 70,92 77.5,108 85,92 92.5,108 100,92 107.5,108 115,92 122.5,108 130,92 137.5,108 145,92 152.5,108 160,100 170,100" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="250,100 260,100 267.5,108 275,92 282.5,108 290,92 297.5,108 305,92 312.5,108 320,92 327.5,108 335,92 342.5,108 350,92 357.5,108 365,92 372.5,108 380,100 390,100" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="210" y="100" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.2 kg</text></svg>', 'A 1.2 kg trolley on a horizontal track held between two springs fixed to walls; together the springs have a spring constant of 300 N m⁻¹.'),
('d8a84b2b-c643-544f-885a-1e33d0f8d3ed', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 14, 14, 'Which change would increase the natural frequency of a mass–spring system?', NULL, 1, 'multiple_choice'::answer_type, 'Using a stiffer spring', NULL, false, NULL, false, NULL, 'f = (1/2π)√(k/m): a larger k gives a higher frequency. Amplitude does not affect it for a perfect spring. Mark scheme (1 mark). B1: C (Using a stiffer spring).', 1, NULL, NULL),
('37b5ddb3-c3a1-5390-b18a-0e3c4c23888f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 15, 15, 'Which change would lengthen the period of a simple pendulum?', NULL, 1, 'multiple_choice'::answer_type, 'Making the string longer', NULL, false, NULL, false, NULL, 'T = 2π√(L/g): only L and g matter. A longer string or weaker gravity gives a longer period. Mark scheme (1 mark). B1: A (Making the string longer).', 1, NULL, NULL),
('d2c7c6b7-716d-55ce-9192-48998a703e43', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 16, 16, 'A toy bird hangs from the ceiling on a spring and bobs up and down once every 0.50 s. Its mass is 0.25 kg. What is the stiffness (spring constant) of the spring?', NULL, 1, 'numeric'::answer_type, '39.48', 'N m⁻¹', false, NULL, false, NULL, 'T = 2π√(m/k), so k = 4π²m/T² = 4π² × 0.25 ÷ 0.50² = 39.5 N m⁻¹. Mark scheme (2 marks). C1: rearranged for k. A1: k = 39.5 N m⁻¹.', 2, NULL, NULL),
('71b5a394-b397-5ea8-9861-fac1381f4090', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 17, 17, 'A tuning fork is struck and left to ring. What happens to the frequency of its vibration as the sound dies away?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'The fork vibrates freely at its natural frequency. Damping reduces the amplitude, not the frequency (for light damping). Mark scheme (1 mark). B1: D (It stays the same).', 1, NULL, NULL),
('970f1aa9-df3e-5d8d-90e8-e94fb17ffa7f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 18, 18, 'A mass–spring system has a natural frequency of 3.2 Hz. At what driving frequency would you expect resonance?', NULL, 1, 'multiple_choice'::answer_type, '3.2 Hz', NULL, false, NULL, false, NULL, 'Resonance occurs when the driving frequency equals the natural frequency, 3.2 Hz. (20 Hz is the angular frequency, 2π × 3.2 rad s⁻¹.). Mark scheme (1 mark). B1: B (3.2 Hz).', 1, NULL, NULL),
('296ef498-a6ae-511d-bdc1-132c5e6495a9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 19, 19, 'A "seconds pendulum" has a period of exactly 2.0 s. Calculate its length. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '0.994', 'm', false, NULL, false, NULL, 'L = gT²/4π² = 9.81 × 2.0² ÷ (4π²) = 0.994 m. Mark scheme (2 marks). C1: T = 2π√(L/g) rearranged. A1: L = 0.994 m.', 2, NULL, NULL),
('d65e967f-05a1-5154-96c6-e4246ceea47d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 20, 20, 'Which is an example of a forced oscillation?', NULL, 1, 'multiple_choice'::answer_type, 'The vibration of a car body caused by the engine running', NULL, false, NULL, false, NULL, 'The running engine supplies a periodic force at its own frequency, so the body vibrates at that driving frequency. Mark scheme (1 mark). B1: C (The vibration of a car body caused by the engine running).', 1, NULL, NULL),
('3b862323-9657-5600-a980-bf3a5fc3e6a4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 21, 21, 'Two pendulums have lengths 0.25 m and 1.00 m. What is the ratio (period of the longer)/(period of the shorter)?', NULL, 1, 'multiple_choice'::answer_type, '2', NULL, false, NULL, false, NULL, 'T ∝ √L: √(1.00/0.25) = √4 = 2. Mark scheme (1 mark). B1: A (2).', 1, NULL, NULL),
('dc8bfe47-dc4e-5844-afce-be617399c277', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 22, 22, 'A car of mass 1200 kg bounces on its suspension with a frequency of 1.5 Hz. Treating it as a mass on a single spring, calculate the effective spring constant.', NULL, 1, 'numeric'::answer_type, '1.066e5', 'N m⁻¹', false, NULL, false, NULL, 'k = 4π²mf² = 4π² × 1200 × 1.5² = 1.07 × 10⁵ N m⁻¹. Mark scheme (2 marks). C1: f = (1/2π)√(k/m) rearranged. A1: k = 1.07 × 10⁵ N m⁻¹.', 2, NULL, NULL),
('f62c7af0-e800-5f5e-b926-ee65681f4a13', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 23, 23, 'A 0.15 kg mass on a 60 N m⁻¹ spring oscillates freely. A second mass of 0.45 kg is added. Calculate the new natural frequency.', NULL, 2, 'numeric'::answer_type, '1.592', 'Hz', false, NULL, false, NULL, 'Total mass = 0.15 + 0.45 = 0.60 kg. f = (1/2π)√(k/m) = (1 ÷ 2π) × √(60 ÷ 0.60) = 1.59 Hz (it was 3.18 Hz: four times the mass halves f). Mark scheme (3 marks). C1: total mass. C1: f = (1/2π)√(k/m). C1: substitution.', 3, NULL, NULL),
('a1846040-c2eb-5556-8ae3-6fdd339b5b52', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 24, 24, 'A pendulum clock keeps correct time with a period of 2.000 s. On a hot day the pendulum expands and its length increases by 0.10 %. By what percentage does the period increase?', NULL, 2, 'numeric'::answer_type, '0.04999', '%', false, NULL, false, NULL, 'T ∝ √L. New T/old T = √1.0010 = 1.00050, so the increase = (1.00050 − 1) × 100 = 0.050 % — the clock runs slow. Mark scheme (3 marks). C1: T ∝ √L. C1: ratio. C1: percentage.', 3, NULL, NULL),
('2950b659-e222-5252-a524-a1b3c9b75045', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 25, 25, 'A mass hangs on a spring and is driven up and down by a vibrator at a frequency well below its natural frequency. How does the mass move?', NULL, 2, 'multiple_choice'::answer_type, 'It oscillates at the driving frequency with a small amplitude, roughly in step with the driver', NULL, false, NULL, false, NULL, 'Far below resonance the mass simply follows the driver: same frequency, small amplitude, nearly in phase. At resonance the amplitude is large and the phase lag is a quarter cycle; well above resonance the mass is out of phase. Mark scheme (3 marks). C1: forced at driving frequency. C1: small amplitude, in phase below resonance. A1: D (It oscillates at the driving frequency with a small amplitude, roughly in step with the driver).', 3, NULL, NULL),
('06276ff1-fcab-5d8d-94ff-2e8319ad799c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 26, 26, 'A pendulum of length 1.20 m is taken from the Earth to the Moon, where g = 1.62 N kg⁻¹. Calculate its period on the Moon.', NULL, 2, 'numeric'::answer_type, '5.408', 's', false, NULL, false, NULL, 'T = 2π√(L/g) = 2π × √(1.20 ÷ 1.62) = 5.41 s (on Earth it was 2.20 s). Mark scheme (3 marks). C1: T = 2π√(L/g). C1: Moon value of g. A1: T = 5.41 s.', 3, NULL, NULL),
('3360c634-32c7-535a-86cc-a12bc558b1c7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 27, 27, 'A spring stretches by 6.0 cm when a 0.30 kg mass is hung on it. Calculate the period of vertical oscillations of the mass. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.4914', 's', false, NULL, false, NULL, 'k = mg/x = 0.30 × 9.81 ÷ 0.060 = 49.1 N m⁻¹. T = 2π√(m/k) = 2π × √(0.30 ÷ 49.05) = 0.491 s (equivalently 2π√(x/g)). Mark scheme (4 marks). C1: k = mg/x. C1: x in metres. C1: T = 2π√(m/k). A1: T = 0.491 s.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fg6a1715b8-t fg6a1715b8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6a1715b8-t">Mass on a spring</title><desc id="fg6a1715b8-d">A 0.30 kg mass hanging at rest on a spring, which it has stretched by 6.0 cm from its unstretched length.</desc><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="130,40 130,50 121,56.9 139,63.8 121,70.6 139,77.5 121,84.4 139,91.2 121,98.1 139,105 121,111.9 139,118.8 121,125.6 139,132.5 121,139.4 139,146.2 121,153.1 130,160 130,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.30 kg</text><line x1="170" y1="140" x2="210" y2="140" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><text x="214" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">unstretched end</text><polygon points="190,140 193,146.3 187,146.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="190" y1="144.9" x2="190" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="190,170 187,163.7 193,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="196" y="155" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">6.0 cm</text></svg>', 'A 0.30 kg mass hanging at rest on a spring, which it has stretched by 6.0 cm from its unstretched length.'),
('7392cba6-4d53-5ed5-ad24-4e463034fb28', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 28, 28, 'Why does a heavier bob not change the period of a simple pendulum?', NULL, 2, 'multiple_choice'::answer_type, 'Both the restoring force and the inertia are proportional to the mass, so the mass cancels', NULL, false, NULL, false, NULL, 'Restoring force ≈ mgθ and the acceleration = force/m = gθ, independent of m. So T = 2π√(L/g). Mark scheme (3 marks). C1: restoring force ∝ m. C1: inertia ∝ m, cancels. A1: B (Both the restoring force and the inertia are proportional to the mass, so the mass cancels).', 3, NULL, NULL),
('b3749489-7c8f-5337-8b64-e77a00d3f5de', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 29, 29, 'A wobbly bridge has a natural frequency of 0.95 Hz for sideways sway. Pedestrians walk at 1.9 steps per second, each step pushing sideways alternately left and right. Calculate the frequency of the sideways driving force and comment.', NULL, 2, 'numeric'::answer_type, '0.95', 'Hz', false, NULL, false, NULL, 'Each full left–right cycle takes two steps: f = 1.9 ÷ 2 = 0.95 Hz, equal to the natural frequency, so the bridge resonates. Mark scheme (3 marks). C1: two steps per sideways cycle. B1: equals natural frequency → resonance. A1: f = 0.95 Hz.', 3, NULL, NULL),
('5603e34a-0c79-596e-9f5e-8b9997ce554d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 30, 30, 'A washing machine drum (effective mass 80 kg) sits on springs with total spring constant 2.0 × 10⁴ N m⁻¹. At what drum rotation rate, in rev min⁻¹, will it shake most violently?', NULL, 2, 'numeric'::answer_type, '151', 'rev min⁻¹', false, NULL, false, NULL, 'f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(2.0 × 10⁴ ÷ 80) = 2.52 Hz. The drum drives the machine at its rotation rate, so resonance at 2.516 × 60 = 151 rev min⁻¹. Mark scheme (3 marks). C1: natural frequency. C1: driving frequency = rotation rate. C1: convert to rev min⁻¹.', 3, NULL, NULL),
('6d88656b-422d-5b2a-bf5d-5a1b5a2cd91b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 31, 31, 'A mass–spring system and a simple pendulum both have period 1.0 s on Earth. They are taken to Mars, where g is smaller. Which is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The pendulum''s period increases; the mass–spring period is unchanged', NULL, false, NULL, false, NULL, 'T_spring = 2π√(m/k) contains no g. T_pendulum = 2π√(L/g) increases when g decreases. Mark scheme (3 marks). C1: spring period independent of g. C1: pendulum period ∝ 1/√g. A1: C (The pendulum''s period increases; the mass–spring period is unchanged).', 3, NULL, NULL),
('dabc2679-5a4d-5335-8244-cf44c3464e62', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 32, 32, 'A 0.50 kg mass on a single spring oscillates with period 0.80 s. Two identical springs are now placed side by side (in parallel) to support the same mass. Calculate the new period.', NULL, 2, 'numeric'::answer_type, '0.5657', 's', false, NULL, false, NULL, 'k = 4π²m/T² = 4π² × 0.50 ÷ 0.80² = 30.8 N m⁻¹. In parallel, k = 2 × 30.8 = 61.7 N m⁻¹. T = 2π√(m/k) = 2π × √(0.50 ÷ 61.69) = 0.566 s. Mark scheme (4 marks). C1: k from first period. C1: parallel springs double k. C1: new T (or T/√2). A1: T = 0.566 s.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fg7c068dbb-t fg7c068dbb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7c068dbb-t">Two springs side by side</title><desc id="fg7c068dbb-d">A 0.50 kg mass supported by two identical springs side by side (in parallel). On one spring alone its period was 0.80 s.</desc><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="112,40 112,50 103,56.9 121,63.8 103,70.6 121,77.5 103,84.4 121,91.2 103,98.1 121,105 103,111.9 121,118.8 103,125.6 121,132.5 103,139.4 121,146.2 103,153.1 112,160 112,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="148,40 148,50 139,56.9 157,63.8 139,70.6 157,77.5 139,84.4 157,91.2 139,98.1 157,105 139,111.9 157,118.8 139,125.6 157,132.5 139,139.4 157,146.2 139,153.1 148,160 148,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.50 kg</text></svg>', 'A 0.50 kg mass supported by two identical springs side by side (in parallel). On one spring alone its period was 0.80 s.'),
('f91dcff2-9caa-563d-9ae8-a749dc03c5dd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 33, 33, 'A student times a pendulum swinging through 20° and finds its period is slightly longer than 2π√(L/g). Why?', NULL, 2, 'multiple_choice'::answer_type, 'The formula assumes small angles; at larger amplitudes the restoring force is less than proportional to displacement', NULL, false, NULL, false, NULL, 'The pendulum is only approximately simple harmonic: the restoring force ∝ sin θ, not θ. At 20° the period is about 0.8 % longer. Mark scheme (3 marks). C1: small-angle approximation. C1: sin θ < θ. A1: A (The formula assumes small angles; at larger amplitudes the restoring force is less than proportional to displacement).', 3, NULL, NULL),
('062072b0-8d09-5036-be60-334bd155ed54', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 34, 34, 'A diving board vibrates at 2.4 Hz when a diver of mass 60 kg stands on its end. Treating the board as a light spring, calculate its spring constant.', NULL, 2, 'numeric'::answer_type, '13644', 'N m⁻¹', false, NULL, false, NULL, 'k = 4π²mf² = 4π² × 60 × 2.4² = 1.36 × 10⁴ N m⁻¹. Mark scheme (3 marks). C1: f = (1/2π)√(k/m). C1: rearranged. A1: k = 1.36 × 10⁴ N m⁻¹.', 3, NULL, NULL),
('29b3fe3e-b36d-5ca6-82e1-5fae06299621', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 35, 35, 'A child pushes a playground swing. To make the amplitude grow, how often should she push?', NULL, 2, 'multiple_choice'::answer_type, 'Once per swing, at the swing''s natural frequency, as it moves away from her', NULL, false, NULL, false, NULL, 'Pushing in time with the natural frequency, in the direction of motion, transfers energy every cycle: resonance. Mark scheme (3 marks). C1: driving frequency = natural frequency. C1: in phase with motion. A1: D (Once per swing, at the swing''s natural frequency, as it moves away from her).', 3, NULL, NULL),
('02c82ce6-c51a-5e48-8601-fd243c13166c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 36, 36, 'A pendulum of length 0.80 m is set swinging. How many complete oscillations does it make in one minute? Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '33.44', NULL, false, 0.02, false, NULL, 'T = 2π√(L/g) = 2π × √(0.80 ÷ 9.81) = 1.79 s. In 60 s: 60 ÷ 1.794 = 33.4 oscillations. Mark scheme (4 marks). C1: T = 2π√(L/g). C1: substitution. C1: 60/T. A1: n = 33.4.', 4, NULL, NULL),
('ff1d4d4a-9563-5488-91db-89af9aa702e2', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 37, 37, 'An atom in a crystal is modelled as a mass of 4.7 × 10⁻²⁶ kg on a spring of constant 30 N m⁻¹. Calculate the natural frequency of its vibration.', NULL, 2, 'numeric'::answer_type, '4.021e12', 'Hz', false, NULL, false, NULL, 'f = (1/2π)√(k/m) = (1 ÷ 2π) × √(30 ÷ 4.7 × 10⁻²⁶) = 4.02 × 10¹² Hz. Mark scheme (3 marks). C1: f = (1/2π)√(k/m). C1: substitution. A1: f = 4.02 × 10¹² Hz.', 3, NULL, NULL),
('fcdd6a45-47cc-5dc9-92a2-9ef9d8007f21', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 38, 38, 'Which pair of quantities determines the natural frequency of a simple pendulum?', NULL, 2, 'multiple_choice'::answer_type, 'Its length and the gravitational field strength', NULL, false, NULL, false, NULL, 'For a simple pendulum f = (1/2π)√(g/L): only the length and the gravitational field strength appear. Mass and (small) amplitude do not. Mark scheme (3 marks). C1: f depends on g. C1: and L only. A1: B (Its length and the gravitational field strength).', 3, NULL, NULL),
('30690944-f4c6-59a5-b124-c4920e9028dd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 39, 39, 'A 70 kg person sits in a car whose suspension springs have a combined constant of 6.0 × 10⁴ N m⁻¹. The car body (without the person) has mass 900 kg. Calculate the natural frequency of vertical bouncing with the person inside.', NULL, 2, 'numeric'::answer_type, '1.252', 'Hz', false, NULL, false, NULL, 'Total mass = 900 + 70 = 970 kg. f = (1/2π)√(k/m) = (1 ÷ 2π) × √(6.0 × 10⁴ ÷ 970) = 1.25 Hz. Mark scheme (3 marks). C1: total mass. C1: f = (1/2π)√(k/m). C1: substitution.', 3, NULL, NULL),
('83696cd8-7380-506c-8878-90a3e66c2c5a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 40, 40, 'A student measures the period T of a simple pendulum for different lengths L: L = 0.20, 0.40, 0.60, 0.80, 1.00 m; T = 0.90, 1.27, 1.55, 1.79, 2.01 s. (a) State what graph gives a straight line through the origin. (b) Explain how g is found from its gradient. (c) Use the last reading to estimate g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '9.772', 'N kg⁻¹', false, NULL, false, NULL, '(a) T² against L. (b) T² = (4π²/g)L, so gradient = 4π²/g and g = 4π²/gradient. (c) gradient ≈ 2.01² ÷ 1.00 = 4.04 s² m⁻¹, g = 4π² ÷ 4.040 = 9.77 N kg⁻¹. Mark scheme (6 marks). B1: T² against L. M1: T² = 4π²L/g. A1: g = 4π²/gradient. C1: gradient. C1: substitution. A1: g = 9.77 N kg⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 438" role="img" aria-labelledby="fge1663b07-t fge1663b07-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge1663b07-t">Period against length</title><desc id="fge1663b07-d">Table and graph of the period of a simple pendulum against its length: L = 0.20, 0.40, 0.60, 0.80, 1.00 m give T = 0.90, 1.27, 1.55, 1.79, 2.01 s, a curve that rises less and less steeply.</desc><g transform="translate(0,0)"><rect x="140.7" y="8" width="118.7" height="168" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="140.7" y="8" width="118.7" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">L / m</text><text x="230.7" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">T / s</text><line x1="202" y1="8" x2="202" y2="176" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="140.7" y1="36" x2="259.4" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.20</text><text x="230.7" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.90</text><line x1="140.7" y1="64" x2="259.4" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.40</text><text x="230.7" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.27</text><line x1="140.7" y1="92" x2="259.4" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.60</text><text x="230.7" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.55</text><line x1="140.7" y1="120" x2="259.4" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.80</text><text x="230.7" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.79</text><line x1="140.7" y1="148" x2="259.4" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.3" y="162" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.00</text><text x="230.7" y="162" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.01</text></g><g transform="translate(0,188)"><line x1="33" y1="34" x2="33" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="96.5" y1="34" x2="96.5" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="159.9" y1="34" x2="159.9" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="223.4" y1="34" x2="223.4" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="286.8" y1="34" x2="286.8" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350.3" y1="34" x2="350.3" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="202" x2="382" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="163.8" x2="382" y2="163.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="125.6" x2="382" y2="125.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="87.5" x2="382" y2="87.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="49.3" x2="382" y2="49.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="202" x2="388" y2="202" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="202" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,202 385.7,205 385.7,199" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="202" x2="33" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="96.5" y1="202" x2="96.5" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="96.5" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="159.9" y1="202" x2="159.9" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="159.9" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="223.4" y1="202" x2="223.4" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="223.4" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="286.8" y1="202" x2="286.8" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="286.8" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.8</text><line x1="350.3" y1="202" x2="350.3" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="350.3" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="202" x2="33" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="163.8" x2="33" y2="163.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="163.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="125.6" x2="33" y2="125.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="125.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="87.5" x2="33" y2="87.5" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="87.5" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="29" y1="49.3" x2="33" y2="49.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="49.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="207.5" y="234" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">L / m</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">T / s</text><line x1="92.5" y1="129.3" x2="100.5" y2="137.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="92.5" y1="137.3" x2="100.5" y2="129.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155.9" y1="101" x2="163.9" y2="109" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155.9" y1="109" x2="163.9" y2="101" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="219.4" y1="79.6" x2="227.4" y2="87.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="219.4" y1="87.6" x2="227.4" y2="79.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="282.8" y1="61.3" x2="290.8" y2="69.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="282.8" y1="69.3" x2="290.8" y2="61.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="44.5" x2="354.3" y2="52.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="52.5" x2="354.3" y2="44.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of the period of a simple pendulum against its length: L = 0.20, 0.40, 0.60, 0.80, 1.00 m give T = 0.90, 1.27, 1.55, 1.79, 2.01 s, a curve that rises less and less steeply.'),
('f186fee7-3d08-523b-9c80-8cfe3fd8dc51', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 41, 41, 'A spring extends by 4.9 cm when a 0.20 kg mass hangs at rest on it. The mass is pulled down a further 3.0 cm and released. (a) Calculate the spring constant. (b) Calculate the period of the oscillations. (c) State the amplitude and explain why it does not affect the period. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.4441', 's', false, NULL, false, NULL, '(a) k = mg/x = 0.20 × 9.81 ÷ 0.049 = 40.0 N m⁻¹. (b) T = 2π√(m/k) = 2π × √(0.20 ÷ 40.04) = 0.444 s. (c) Amplitude = 3.0 cm. For s.h.m. the restoring force is proportional to displacement, so a larger amplitude means a proportionally larger force and speed: T stays the same. Mark scheme (5 marks). C1: k = mg/x. A1: k. C1: T = 2π√(m/k). A1: T = 0.444 s. B1: amplitude 3.0 cm, period independent.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fg99518980-t fg99518980-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg99518980-t">Pulling the mass down</title><desc id="fg99518980-d">A 0.20 kg mass hanging at rest on a spring that it has extended by 4.9 cm; the mass is then pulled down a further 3.0 cm and released.</desc><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="130,40 130,50 121,56.9 139,63.8 121,70.6 139,77.5 121,84.4 139,91.2 121,98.1 139,105 121,111.9 139,118.8 121,125.6 139,132.5 121,139.4 139,146.2 121,153.1 130,160 130,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.20 kg</text><line x1="170" y1="140" x2="210" y2="140" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><text x="214" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">unstretched end</text><polygon points="190,140 193,146.3 187,146.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="190" y1="144.9" x2="190" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="190,170 187,163.7 193,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="196" y="155" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.9 cm</text><polygon points="80,210 83,216.3 77,216.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="80" y1="214.9" x2="80" y2="245.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="80,250 77,243.7 83,243.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="74" y="230" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3.0 cm</text><rect x="100" y="210" width="60" height="40" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="130" y="262" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">pulled down</text></svg>', 'A 0.20 kg mass hanging at rest on a spring that it has extended by 4.9 cm; the mass is then pulled down a further 3.0 cm and released.'),
('64e5d259-51c3-598e-88b3-c5cc8ef54167', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 42, 42, 'A mass of 0.50 kg on a spring of constant 50 N m⁻¹ is driven by a vibrator whose frequency can be varied. (a) Calculate the natural frequency. (b) Describe how the amplitude of the mass varies as the driving frequency is increased from 0.5 Hz to 3.0 Hz. (c) The mass is replaced by a 2.0 kg mass. Calculate the new resonant frequency. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.7958', 'Hz', false, NULL, false, NULL, '(a) f₀ = (1/2π)√(k/m) = (1 ÷ 2π) × √(50 ÷ 0.50) = 1.59 Hz. (b) The amplitude is small at low frequency, rises to a sharp maximum at about 1.6 Hz (resonance), then falls again at higher frequencies. (c) f₀ = (1 ÷ 2π) × √(50 ÷ 2.0) = 0.796 Hz. Mark scheme (6 marks). C1: f₀ formula. A1: 1.6 Hz. B1: amplitude peaks at f₀. B1: small away from f₀. C1: new mass. A1: 0.80 Hz.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fgcdd00dc3-t fgcdd00dc3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcdd00dc3-t">Driven mass–spring system</title><desc id="fgcdd00dc3-d">A 0.50 kg mass on a spring of constant 50 N m⁻¹ hangs from a vibrator that drives the top of the spring up and down at a frequency that can be varied.</desc><rect x="90" y="10" width="80" height="26" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="23" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">vibrator</text><polygon points="186,30 183.5,24.6 188.5,24.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="186" y1="25.8" x2="186" y2="10.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="186,6 188.5,11.4 183.5,11.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><polyline points="130,36 130,46 121,52.9 139,59.8 121,66.6 139,73.5 121,80.4 139,87.2 121,94.1 139,101 121,107.9 139,114.8 121,121.6 139,128.5 121,135.4 139,142.2 121,149.1 130,156 130,166" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="166" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="186" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.50 kg</text><text x="152" y="101" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">k = 50 N m⁻¹</text></svg>', 'A 0.50 kg mass on a spring of constant 50 N m⁻¹ hangs from a vibrator that drives the top of the spring up and down at a frequency that can be varied.'),
('d055ea59-6638-57fc-917a-92bd2fc2fca5', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 43, 43, 'A spacecraft has no scales, so astronauts measure their mass by sitting in a chair attached to a spring (k = 600 N m⁻¹). The chair alone has mass 12 kg. An astronaut in the chair oscillates with period 2.30 s. (a) Explain why ordinary scales would not work in orbit. (b) Calculate the total oscillating mass. (c) Calculate the astronaut''s mass. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '68.4', 'kg', false, NULL, false, NULL, '(a) Everything is in free fall, so there is no contact force for scales to measure. (b) m = kT²/4π² = 600 × 2.30² ÷ (4π²) = 80.4 kg. (c) astronaut = 80.40 − 12 = 68.4 kg. Mark scheme (5 marks). B1: free fall / no weight reading. C1: T = 2π√(m/k). A1: total mass. C1: subtract chair. A1: m = 68.4 kg.', 5, NULL, NULL),
('3e90495b-1558-5b80-8ae3-6cf576dcfc7b', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 44, 44, 'A pendulum consists of a 50 g bob on a 1.50 m string. It is displaced by 6.0 cm and released. (a) Calculate its period. (b) Calculate its maximum speed, using v_max = ωA. (c) Calculate the maximum tension in the string. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.4913', 'N', false, NULL, false, NULL, '(a) T = 2π√(L/g) = 2π × √(1.50 ÷ 9.81) = 2.46 s. (b) ω = 2π/T = 2.56 rad s⁻¹, v = ωA = 2.56 × 0.060 = 0.153 m s⁻¹. (c) At the bottom T − mg = mv²/L: T = 0.050 × 9.81 + 0.050 × 0.153² ÷ 1.50 = 0.4913 N. Mark scheme (6 marks). C1: T = 2π√(L/g). A1: T. C1: v = ωA. A1: v. C1: T − mg = mv²/L. A1: T = 0.4913 N.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fg43a8b4ce-t fg43a8b4ce-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg43a8b4ce-t">Simple pendulum</title><desc id="fg43a8b4ce-d">A pendulum with a 50 g bob on a 1.50 m string, displaced sideways by 6.0 cm from its equilibrium position (dashed) and released.</desc><line x1="100" y1="40" x2="200" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="40" x2="98" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="118" y1="40" x2="110" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130" y1="40" x2="122" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="142" y1="40" x2="134" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="154" y1="40" x2="146" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166" y1="40" x2="158" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="178" y1="40" x2="170" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="40" x2="182" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="40" x2="150" y2="250" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="150" y1="40" x2="191.6" y2="235.6" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="191.6" cy="235.6" r="11" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="150" cy="240" r="11" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><text x="142" y="140" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.50 m</text><text x="207.6" y="235.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">50 g</text><polygon points="150,266 156.3,263 156.3,269" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="154.9" y1="266" x2="186.7" y2="266" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="191.6,266 185.2,269 185.2,263" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="170.8" y="278" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 cm</text></svg>', 'A pendulum with a 50 g bob on a 1.50 m string, displaced sideways by 6.0 cm from its equilibrium position (dashed) and released.'),
('6921ff44-3130-5f52-8c41-23503fc9eaae', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 45, 45, 'Two different springs, A (k = 40 N m⁻¹) and B (k = 160 N m⁻¹), each carry a 0.40 kg mass. (a) Calculate both natural frequencies. (b) Explain which system needs a larger force to reach the same amplitude. (c) What mass would give spring A the same natural frequency as spring B with 0.40 kg? Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.1', 'kg', false, NULL, false, NULL, '(a) f_A = (1 ÷ 2π) × √(40 ÷ 0.40) = 1.59 Hz, f_B = (1 ÷ 2π) × √(160 ÷ 0.40) = 3.18 Hz. (b) B: the force for a displacement x is kx, and k is four times larger. (c) f ∝ √(k/m): need k/m equal, so m = 0.40 × 40 ÷ 160 = 0.10 kg. Mark scheme (5 marks). C1: f = (1/2π)√(k/m). A1: both frequencies. B1: B needs larger force (F = kx). C1: k/m equal. A1: m = 0.10 kg.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 530 300" role="img" aria-labelledby="fg4ff09a21-t fg4ff09a21-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4ff09a21-t">Two springs</title><desc id="fg4ff09a21-d">Spring A (k = 40 N m⁻¹) and spring B (k = 160 N m⁻¹), each carrying a 0.40 kg mass.</desc><g transform="translate(0,0)"><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="130,40 130,50 121,56.9 139,63.8 121,70.6 139,77.5 121,84.4 139,91.2 121,98.1 139,105 121,111.9 139,118.8 121,125.6 139,132.5 121,139.4 139,146.2 121,153.1 130,160 130,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.40 kg</text><text x="152" y="105" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">A: k = 40 N m⁻¹</text></g><g transform="translate(270,0)"><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="130,40 130,50 121,56.9 139,63.8 121,70.6 139,77.5 121,84.4 139,91.2 121,98.1 139,105 121,111.9 139,118.8 121,125.6 139,132.5 121,139.4 139,146.2 121,153.1 130,160 130,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.40 kg</text><text x="152" y="105" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B: k = 160 N m⁻¹</text></g></svg>', 'Spring A (k = 40 N m⁻¹) and spring B (k = 160 N m⁻¹), each carrying a 0.40 kg mass.'),
('4101c02a-0792-5b13-8e3f-e849f8b8fa45', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 46, 46, 'A tall building sways with a natural frequency of 0.20 Hz. Engineers fit a "tuned mass damper": a 3.0 × 10⁵ kg block on springs near the top. (a) State the frequency to which the damper should be tuned and explain why. (b) Calculate the spring constant needed. (c) Explain how the damper reduces the sway. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.737e5', 'N m⁻¹', false, NULL, false, NULL, '(a) 0.20 Hz — the building''s natural frequency, so the damper resonates with it. (b) k = 4π²mf² = 4π² × 3.0 × 10⁵ × 0.20² = 4.74 × 10⁵ N m⁻¹. (c) The block swings out of phase with the building, exerting forces that oppose the sway; its own damping removes the energy. Mark scheme (6 marks). B1: tuned to 0.20 Hz. B1: resonance of damper. C1: k = 4π²mf². A1: k = 4.74 × 10⁵ N m⁻¹. B1: out-of-phase forces. B1: energy dissipated.', 6, NULL, NULL),
('8dc25ae3-0a3a-52ef-a9d8-4a50d3ecc948', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 47, 47, 'A glider of mass 0.25 kg on a horizontal air track is held between two stretched springs, each of constant 12 N m⁻¹. When displaced, both springs push it back. (a) Explain why the effective spring constant is 24 N m⁻¹. (b) Calculate the period. (c) Calculate how many oscillations it makes in 30 s. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.6413', 's', false, NULL, false, NULL, '(a) Displaced by x, one spring stretches and the other compresses by x: each gives a restoring force 12x, total 24x. (b) T = 2π√(m/k) = 2π × √(0.25 ÷ 24) = 0.641 s. (c) 30 ÷ 0.6413 = 46.8 oscillations. Mark scheme (5 marks). M1: both springs push towards equilibrium. A1: 24 N m⁻¹. C1: T = 2π√(m/k). A1: T = 0.641 s. B1: number of oscillations.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg662aa294-t fg662aa294-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg662aa294-t">Glider between springs</title><desc id="fg662aa294-d">A 0.25 kg glider on a horizontal air track held between two stretched springs, each of spring constant 12 N m⁻¹, fixed to the ends of the track.</desc><rect x="20" y="50" width="10" height="80" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><rect x="390" y="50" width="10" height="80" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="130" x2="400" y2="130" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="170" y="80" width="80" height="40" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polyline points="30,100 40,100 47.5,108 55,92 62.5,108 70,92 77.5,108 85,92 92.5,108 100,92 107.5,108 115,92 122.5,108 130,92 137.5,108 145,92 152.5,108 160,100 170,100" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="250,100 260,100 267.5,108 275,92 282.5,108 290,92 297.5,108 305,92 312.5,108 320,92 327.5,108 335,92 342.5,108 350,92 357.5,108 365,92 372.5,108 380,100 390,100" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="210" y="100" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.25 kg</text><text x="100" y="78" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 N m⁻¹</text><text x="320" y="78" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 N m⁻¹</text></svg>', 'A 0.25 kg glider on a horizontal air track held between two stretched springs, each of spring constant 12 N m⁻¹, fixed to the ends of the track.'),
('2f3e4d05-72c7-59d5-9285-a3c60929c346', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 48, 48, 'A pendulum clock has a period of 2.000 s at sea level (g = 9.810 N kg⁻¹). It is taken up a mountain where g = 9.795 N kg⁻¹. (a) Calculate its new period. (b) Calculate how many seconds it loses in one day. (c) Suggest how the pendulum could be adjusted to keep correct time. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '66.08', 's', false, NULL, false, NULL, '(a) T ∝ 1/√g: T = 2.000 × √(9.810 ÷ 9.795) = 2.00153 s. (b) The clock counts swings: in a true day it makes 86400 ÷ 2.00153 swings instead of 43200, so it shows 86400 × √(9.795 ÷ 9.810) seconds: it loses 86400 × (1 − √(9.795 ÷ 9.810)) = 66.1 s. (c) Shorten the pendulum slightly (by the fraction 0.15 %). Mark scheme (6 marks). C1: T ∝ 1/√g. A1: new period. M1: fewer swings counted. C1: time lost. A1: loss = 66.1 s. B1: shorten pendulum.', 6, NULL, NULL),
('bf9c8e6a-39b6-59b6-904e-5f3a380717fc', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 49, 49, 'A bungee jumper of mass 65 kg bounces up and down at the end of the rope, which behaves like a spring of constant 180 N m⁻¹. (a) Calculate the period of the bouncing. (b) Calculate the extension of the rope when she hangs at rest. (c) Explain why the bouncing slowly dies away. Give only the answer to (a). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '3.776', 's', false, NULL, false, NULL, '(a) T = 2π√(m/k) = 2π × √(65 ÷ 180) = 3.78 s. (b) kx = mg: x = 65 × 9.81 ÷ 180 = 3.54 m. (c) Air resistance and internal friction in the rope remove energy (damping), so the amplitude decreases. Mark scheme (5 marks). C1: T = 2π√(m/k). A1: T. C1: kx = mg. A1: T = 3.78 s. B1: damping removes energy.', 5, NULL, NULL),
('260b9505-cf6a-579e-aaf9-087b00799556', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '85916e10-6d16-4317-bbcd-22eb741ac6db', 'a-level', '18.1', '9702 coursebook 18.1 · Free and forced oscillations', 50, 50, 'A student hangs masses on a spring and times 20 oscillations each time: m = 0.10 kg, 20T = 9.0 s; m = 0.40 kg, 20T = 17.8 s. (a) Calculate both periods. (b) Show that the results agree with T ∝ √m. (c) Calculate the spring constant from the 0.40 kg reading. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '19.94', 'N m⁻¹', false, NULL, false, NULL, '(a) T₁ = 9.0 ÷ 20 = 0.45 s, T₂ = 17.8 ÷ 20 = 0.89 s. (b) Mass ×4 should give T ×2: 0.89 ÷ 0.45 = 1.98 ≈ 2. (c) k = 4π²m/T² = 4π² × 0.40 ÷ 0.89² = 19.9 N m⁻¹. Mark scheme (6 marks). A1: both periods. M1: ratio of masses 4, periods 2. A1: ratio ≈ 2. C1: k = 4π²m/T². C1: substitution. A1: k = 19.9 N m⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 100" role="img" aria-labelledby="fg017fd56d-t fg017fd56d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg017fd56d-t">Timings</title><desc id="fg017fd56d-d">Table of timings: m = 0.10 kg gives 20 oscillations in 9.0 s; m = 0.40 kg gives 20 oscillations in 17.8 s.</desc><rect x="129.6" y="8" width="140.8" height="84" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="129.6" y="8" width="140.8" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="163.5" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">m / kg</text><text x="233.9" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">20T / s</text><line x1="197.4" y1="8" x2="197.4" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129.6" y1="36" x2="270.4" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="163.5" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10</text><text x="233.9" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">9.0</text><line x1="129.6" y1="64" x2="270.4" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="163.5" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.40</text><text x="233.9" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">17.8</text></svg>', 'Table of timings: m = 0.10 kg gives 20 oscillations in 9.0 s; m = 0.40 kg gives 20 oscillations in 17.8 s.')
