INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('9e3c22da-d8da-5b55-9c30-358b041d234f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 7, 7, 'A student times 10 oscillations of a mass on a spring as 8.6 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '0.86', 's', false, NULL, false, NULL, 'T = 8.6 ÷ 10 = 0.86 s. Mark scheme (1 mark). A1: T = 0.86 s.', 1, NULL, NULL),
('18bd1e8e-bb59-506f-a907-1df4d14397e7', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 8, 8, 'A heart monitor shows 72 beats in one minute. Calculate the frequency in hertz.', NULL, 1, 'numeric'::answer_type, '1.2', 'Hz', false, NULL, false, NULL, 'f = 72 ÷ 60 = 1.2 Hz. Mark scheme (1 mark). A1: f = 1.2 Hz.', 1, NULL, NULL),
('7373eb95-8a43-5dc4-931e-f78a4fbac097', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 9, 9, 'A guitar string vibrates 330 times each second. Calculate the period of its vibration in milliseconds.', NULL, 1, 'numeric'::answer_type, '3.03 ms', 'ms', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 330 = 0.00303 s. In ms: 0.003030 × 1000 = 3.03 ms. Mark scheme (2 marks). C1: T = 1/f. A1: T = 3.03 ms.', 2, NULL, NULL),
