('ea2ef2e5-1c91-5605-a4a3-942facb73b42', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 14, 14, 'A wing of a hummingbird beats with a frequency of 55 Hz. How many beats does it make in 3.0 s?', NULL, 1, 'numeric'::answer_type, '165', NULL, false, NULL, false, NULL, 'number = ft = 55 × 3.0 = 165. Mark scheme (2 marks). C1: N = ft. A1: beats = 165.', 2, NULL, NULL),
('c78d8c04-754d-51c8-9899-ece2f4f37c57', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 15, 15, 'Why is it better to time 20 oscillations than one?', NULL, 1, 'multiple_choice'::answer_type, 'The reaction-time error is shared over 20 periods, so the percentage uncertainty in T is smaller', NULL, false, NULL, false, NULL, 'Starting and stopping errors (≈ 0.2 s) are the same however many oscillations are timed, so dividing by 20 makes their effect on T much smaller. Mark scheme (1 mark). B1: B (The reaction-time error is shared over 20 periods, so the percentage uncertainty in T is smaller).', 1, NULL, NULL),
('d81b8fbf-9692-5634-873e-6aae28811a0c', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 16, 16, 'A pendulum makes 25 complete oscillations in 40.0 s. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '0.625', 'Hz', false, NULL, false, NULL, 'f = number ÷ time = 25 ÷ 40.0 = 0.625 Hz. Mark scheme (2 marks). C1: f = N/t. A1: f = 0.625 Hz.', 2, NULL, NULL),
