('fc3a2bb4-da5e-55cc-bd28-9afbd5b4e03f', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 18, 18, 'A twanged ruler appears stationary in the light of a strobe flashing 24 times a second, and at no higher flash rate up to 48 Hz. What is the frequency of the ruler?', NULL, 1, 'multiple_choice'::answer_type, '24 Hz', NULL, false, NULL, false, NULL, 'The ruler looks frozen when it completes a whole number of vibrations between flashes. The highest flash rate giving a single frozen image equals its frequency: 24 Hz. Mark scheme (1 mark). B1: A (24 Hz).', 1, NULL, NULL),
('b4965202-4226-507c-aa02-01a22fd42d15', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 19, 19, 'A student says the period of an oscillation is "the time from one end to the other end of the swing". What is wrong?', NULL, 1, 'multiple_choice'::answer_type, 'That is only half a period: the period is the time for one complete oscillation, back to the same point moving the same way', NULL, false, NULL, false, NULL, 'One end to the other is half an oscillation. A full period returns to the starting position with the same direction of motion. Mark scheme (1 mark). B1: D (That is only half a period: the period is the time for one complete oscillation, back to the same point moving the same way).', 1, NULL, NULL),
('28f5ef05-4f17-52a8-acbd-795948d6c4cd', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 20, 20, 'A displacement–time graph shows 6 complete cycles in 1.5 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '0.25', 's', false, NULL, false, NULL, 'T = 1.5 ÷ 6 = 0.25 s. Mark scheme (2 marks). C1: T = t/N. A1: T = 0.25 s.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgc992e47d-t fgc992e47d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc992e47d-t">Displacement against time</title><desc id="fgc992e47d-d">Displacement–time graph showing 6 complete cycles in 1.5 s.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="143.3" y1="34" x2="143.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="262.7" y1="34" x2="262.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="388" y2="138" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,138 385.7,141 385.7,135" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" styl