50.3" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="202" x2="33" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="168.4" x2="33" y2="168.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="168.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="29" y1="134.8" x2="33" y2="134.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="134.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="29" y1="101.2" x2="33" y2="101.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="101.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="29" y1="67.6" x2="33" y2="67.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="67.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.8</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="207.5" y="234" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">m / kg</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">T / s</text><line x1="92.5" y1="130.8" x2="100.5" y2="138.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="92.5" y1="138.8" x2="100.5" y2="130.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155.9" y1="103.9" x2="163.9" y2="111.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155.9" y1="111.9" x2="163.9" y2="103.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="219.4" y1="82.1" x2="227.4" y2="90.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="219.4" y1="90.1" x2="227.4" y2="82.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="282.8" y1="63.6" x2="290.8" y2="71.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="282.8" y1="71.6" x2="290.8" y2="63.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="48.5" x2="354.3" y2="56.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="56.5" x2="354.3" y2="48.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of period against mass: m = 0.10, 0.20, 0.30, 0.40, 0.50 kg give T = 0.40, 0.56, 0.69, 0.80, 0.89 s.'),
('46b76375-ef15-58dc-9ec2-7bab8fe26943', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 39, 39, 'Timing 20 swings of a pendulum gives 35.4 s ± 0.3 s. The length is 0.780 m ± 0.002 m. (a) Calculate g using T = 2π√(L/g). (b) Calculate the percentage uncertainties in T and L. (c) Calculate the percentage uncertainty in g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.951', '%', false, 0.05, false, NULL, '(a) T = 35.4 ÷ 20 = 1.77 s. g = 4π²L/T² = 4π² × 0.780 ÷ 1.77² = 9.83 N kg⁻¹. (b) %T = 0.3 ÷ 35.4 × 100 = 0.847 %, %L = 0.002 ÷ 0.780 × 100 = 0.256 %. (c) g ∝ L/T², so %g = %L + 2 × %T = 0.256 + 2 × 0.847 = 1.95 %. Mark scheme (5 marks). C1: T from 20 swings. A1: g. A1: %T and %L. M1: %g = %L + 2%T. A1: %g = 2.0%.', 5, NULL, NULL),
('362898b9-8dc8-5d3b-b106-1a88b3ca9dbe', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 40, 40, 'A vibrating plate is observed with a stroboscope. The plate appears stationary at flash frequencies of 50 Hz, 25 Hz and 16.7 Hz, but not at any frequency between 50 Hz and 100 Hz. At 100 Hz it appears frozen but with two images. (a) Explain why it appears stationary at several flash frequencies. (b) Deduce the frequency of the plate. (c) Explain the double image at 100 Hz. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '50', 'Hz', false, NULL, false, NULL, '(a) The plate appears frozen whenever it completes a whole number of cycles between flashes: at f, f/2, f/3 … (b) The highest single-image freezing frequency is the plate''s frequency. The others fit: 25 × 2 = 50 and 16.7 × 3 = 50 Hz. (c) At 100 Hz the flashes come twice per cycle, catching the plate at two different positions. Mark scheme (6 marks). B1: whole number of cycles between flashes. M1: f, f/2, f/3 pattern. A1: 50 Hz. B1: 100 Hz = twice per cycle. B1: two positions seen. B1: correct reasoning for highest frequency.', 6, NULL, NULL),
('5af9de0b-11c2-579a-a0ea-b1cbdf6768f4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 41, 41, 'A motion sensor records the displacement x of a trolley oscillating between springs: x = 0 at t = 0, +3.0 cm at t = 0.30 s, 0 at t = 0.60 s, −3.0 cm at t = 0.90 s, 0 at t = 1.20 s. (a) State the amplitude and period. (b) Calculate the maximum speed, using v_max = 2πA/T. (c) State where in the cycle the trolley moves fastest. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.1571', 'm s⁻¹', false, NULL, false, NULL, '(a) A = 3.0 cm, T = 1.20 s. (b) v_max = 2πA/T = 2π × 0.030 ÷ 1.20 = 0.157 m s⁻¹. (c) Passing through x = 0 (t = 0, 0.60 s, 1.20 s). Mark scheme (5 marks). B1: A = 3.0 cm. B1: T = 1.20 s. C1: v_max = 2πA/T. A1: v_max = 0.157 m s⁻¹. B1: at equilibrium.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgafbd9193-t fgafbd9193-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgafbd9193-t">Motion-sensor readings</title><desc id="fgafbd9193-d">Displacement against time from the motion sensor: 0 at t = 0, +3.0 cm at 0.30 s, 0 at 0.60 s, −3.0 cm at 0.90 s and 0 at 1.20 s.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.8" y1="34" x2="110.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="192.2" y1="34" x2="192.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="273.5" y1="34" x2="273.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="354.9" y1="34" x2="354.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="216" x2="382" y2="216" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="60" x2="382" y2="60" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="388" y2="138" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,138 385.7,141 385.7,135" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="138" x2="29.4" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="110.8" y1="138" x2="110.8" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="110.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.3</text><line x1="192.2" y1="138" x2="192.2" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="192.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="273.5" y1="138" x2="273.5" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="273.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.9</text><line x1="354.9" y1="138" x2="354.9" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="354.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.2</text><line x1="25.4" y1="216" x2="29.4" y2="216" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="216" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−3</text><line x1="25.4" y1="138" x2="29.4" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="60" x2="29.4" y2="60" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="60" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">x / cm</text><line x1="25.4" y1="134" x2="33.4" y2="142" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="25.4" y1="142" x2="33.4" y2="134" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106.8" y1="56" x2="114.8" y2="64" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106.8" y1="64" x2="114.8" y2="56" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="269.5" y1="212" x2="277.5" y2="220" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="269.5" y1="220" x2="277.5" y2="212" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="188.2" y1="134" x2="196.2" y2="142" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="188.2" y1="142" x2="196.2" y2="134" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350.9" y1="134" x2="358.9" y2="142" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350.9" y1="142" x2="358.9" y2="134" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Displacement against time from the motion sensor: 0 at t = 0, +3.0 cm at 0.30 s, 0 at 0.60 s, −3.0 cm at 0.90 s and 0 at 1.20 s.'),
('656a9364-c2f7-5a1a-93b3-9fb432bdac62', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 42, 42, 'A student uses a data logger to record a pendulum and finds the amplitude falls from 10.0 cm to 5.0 cm in 30 complete oscillations, each of period 1.20 s. (a) Calculate the time taken for the amplitude to halve. (b) State what fraction of the energy remains when the amplitude has halved. (c) Predict the amplitude after 60 oscillations, assuming the same fractional loss per oscillation. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.5 cm', 'cm', false, NULL, false, NULL, '(a) t = 30 × 1.20 = 36 s. (b) E ∝ A², so (½)² = ¼ of the energy remains. (c) Each 30 oscillations halves the amplitude, so after 60 it is 10.0 ÷ 4 = 2.5 cm. Mark scheme (6 marks). C1: t = 30T. A1: 36 s. B1: E ∝ A². B1: ¼. M1: halving every 30 oscillations. A1: 2.5 cm.', 6, NULL, NULL),
('6eea1cf9-1011-51bf-9dec-bd5076cd46c8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 43, 43, 'An oscilloscope (time base 1.0 ms per division) displays the output of a microphone placed near a vibrating tuning fork. Four complete cycles occupy 9.6 divisions. (a) Calculate the frequency of the fork. (b) The time base is changed to 0.50 ms per division. Calculate how many divisions one cycle now occupies. (c) Explain why the trace height falls slowly while the frequency stays the same. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '416.7', 'Hz', false, NULL, false, NULL, '(a) T = 9.6 × 1.0 ÷ 4 = 2.4 ms. f = 1 ÷ 2.4 × 10⁻³ = 417 Hz. (b) 2.4 ms ÷ 0.50 ms per division = 4.8 divisions. (c) Damping removes energy so the amplitude decreases, but the natural frequency of the fork does not change. Mark scheme (5 marks). C1: T from 4 cycles. A1: f = 417 Hz. C1: divisions = T/time base. A1: 4.8. B1: damping lowers amplitude, frequency unchanged.', 5, NULL, NULL),
('405ed446-6eea-5bfc-b82c-318bab739fc9', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 44, 44, 'A girl on a trampoline bounces with a steady period of 1.6 s. A video shows her rising 1.2 m above the bed at the top of each bounce. (a) Calculate the time she spends in the air on each bounce, assuming she leaves and lands at the same level. (b) Calculate the time in contact with the bed. (c) Explain why this motion is periodic but not simple harmonic. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.6108', 's', false, NULL, false, NULL, '(a) Time to fall 1.2 m: t = √(2h/g) = √(2 × 1.2 ÷ 9.81) = 0.495 s, so air time = 2 × 0.495 = 0.989 s. (b) contact time = 1.6 − 0.9892 = 0.611 s. (c) It repeats regularly, but in the air the acceleration is constant (g), not proportional to displacement. Mark scheme (6 marks). C1: t = √(2h/g). A1: air time. C1: subtract from period. A1: t = 0.611 s. B1: periodic. B1: a not ∝ −x in flight.', 6, NULL, NULL),
('c8812487-617e-502e-86b9-9c337ed91457', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 45, 45, 'A position sensor records an oscillating glider: the displacement is +5.0 cm at t = 0, 0 at t = 0.35 s, −5.0 cm at t = 0.70 s and +5.0 cm again at t = 1.40 s. (a) State the amplitude and period. (b) Calculate the frequency. (c) Calculate the maximum speed of the glider. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.2244', 'm s⁻¹', false, NULL, false, NULL, '(a) A = 5.0 cm, T = 1.40 s. (b) f = 1 ÷ 1.40 = 0.714 Hz. (c) v_max = 2πA/T = 2π × 0.050 ÷ 1.40 = 0.224 m s⁻¹. Mark scheme (5 marks). B1: A = 5.0 cm. B1: T = 1.40 s. A1: f. C1: v_max = 2πA/T. A1: v_max = 0.224 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgb4b70d4b-t fgb4b70d4b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb4b70d4b-t">Position-sensor readings</title><desc id="fgb4b70d4b-d">Displacement against time from the position sensor: +5.0 cm at t = 0, 0 at 0.35 s, −5.0 cm at 0.70 s and +5.0 cm again at 1.40 s.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111.7" y1="34" x2="111.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="194" y1="34" x2="194" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="276.2" y1="34" x2="276.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="358.5" y1="34" x2="358.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="224.7" x2="382" y2="224.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="51.3" x2="382" y2="51.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="388" y2="138" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,138 385.7,141 385.7,135" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="138" x2="29.4" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="111.7" y1="138" x2="111.7" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="111.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.35</text><line x1="194" y1="138" x2="194" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="194" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.70</text><line x1="276.2" y1="138" x2="276.2" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="276.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.05</text><line x1="358.5" y1="138" x2="358.5" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="358.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.40</text><line x1="25.4" y1="224.7" x2="29.4" y2="224.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="224.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−5</text><line x1="25.4" y1="138" x2="29.4" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="51.3" x2="29.4" y2="51.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="51.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">x / cm</text><line x1="190" y1="220.7" x2="198" y2="228.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="228.7" x2="198" y2="220.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="354.5" y1="47.3" x2="362.5" y2="55.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="354.5" y1="55.3" x2="362.5" y2="47.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="107.7" y1="134" x2="115.7" y2="142" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="107.7" y1="142" x2="115.7" y2="134" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="25.4" y1="47.3" x2="33.4" y2="55.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="25.4" y1="55.3" x2="33.4" y2="47.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Displacement against time from the position sensor: +5.0 cm at t = 0, 0 at 0.35 s, −5.0 cm at 0.70 s and +5.0 cm again at 1.40 s.'),
('b5b13a3d-8138-55e1-8ec1-6c3a2f8d6d3e', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 46, 46, 'A student times a mass–spring system: t₁₀ (time for 10 oscillations) = 6.42, 6.38, 6.45, 6.40 s. (a) Calculate the mean period. (b) Estimate the absolute uncertainty in the period from the spread of readings. (c) The mass is 0.250 kg. Calculate the spring constant. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '24', 'N m⁻¹', false, NULL, false, NULL, '(a) mean t₁₀ = (6.42 + 6.38 + 6.45 + 6.40) ÷ 4 = 6.412 s, so T = 0.6412 s. (b) half-range = (6.45 − 6.38) ÷ 2 = 0.035 s for 10, so ±0.004 s. (c) k = 4π²m/T² = 4π² × 0.250 ÷ 0.6412² = 24.0 N m⁻¹. Mark scheme (6 marks). C1: mean. A1: T. B1: uncertainty from half-range ÷ 10. C1: k = 4π²m/T². C1: substitution. A1: k = 24.0 N m⁻¹.', 6, NULL, NULL),
('2187555c-a2d8-5512-85de-18a697237214', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 47, 47, 'A digital camera filming at 240 frames per second records a vibrating spring. The spring takes 18 frames for one complete oscillation, and its ends move 12 mm apart. (a) Calculate the period. (b) State the amplitude. (c) Calculate the maximum speed of the end of the spring. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.5027', 'm s⁻¹', false, NULL, false, NULL, '(a) T = 18 ÷ 240 = 0.075 s. (b) A = 12 ÷ 2 = 6.0 mm. (c) v_max = 2πA/T = 2π × 0.0060 ÷ 0.075 = 0.503 m s⁻¹. Mark scheme (5 marks). C1: T = frames/frame rate. A1: T. B1: A = 6.0 mm. C1: v_max = 2πA/T. A1: v_max = 0.503 m s⁻¹.', 5, NULL, NULL),
('c18d30ad-be6b-5b53-b789-2c7356ed9422', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'a3159ca9-af9c-407a-9d2b-1f70f0f4bf7b', 'a-level', '18.2', '9702 coursebook 18.2 · Observing oscillations', 48, 48, 'An oscilloscope with time base 5.0 ms per division and y-gain 2.0 V per division shows the output of a vibration sensor (1.0 V per mm of displacement). One cycle spans 7.2 divisions and the peak-to-peak height is 4.4 divisions. (a) Calculate the frequency. (b) Calculate the amplitude of the vibration in mm. (c) Calculate the maximum speed of the vibrating surface. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.7679', 'm s⁻¹', false, NULL, false, NULL, '(a) T = 7.2 × 5.0 = 36 ms, f = 1 ÷ 0.036 = 27.8 Hz. (b) peak-to-peak = 4.4 × 2.0 = 8.8 V, so amplitude = 4.4 V = 4.4 mm. (c) v_max = 2πfA = 2π × 27.78 × 0.0044 = 0.768 m s⁻¹. Mark scheme (6 marks). C1: T from time base. A1: f. C1: voltage to displacement. A1: A = 4.4 mm. C1: v_max = 2πfA. A1: v_max = 0.768 m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 338" role="img" aria-labelledby="fg9863aa18-t fg9863aa18-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9863aa18-t">Oscilloscope trace</title><desc id="fg9863aa18-d">The output of a vibration sensor (1.0 V per mm) on an oscilloscope: one cycle spans 7.2 divisions and the peak-to-peak height is 4.4 divisions. Y-gain 2.0 V per division; time base 5.0 ms per division.</desc><rect x="20" y="12" width="340" height="272" rx="6" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="54" y1="12" x2="54" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="12" x2="88" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="12" x2="122" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="156" y1="12" x2="156" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="12" x2="190" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224" y1="12" x2="224" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="12" x2="258" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="292" y1="12" x2="292" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="326" y1="12" x2="326" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="46" x2="360" y2="46" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="80" x2="360" y2="80" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="114" x2="360" y2="114" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="148" x2="360" y2="148" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="182" x2="360" y2="182" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="216" x2="360" y2="216" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="250" x2="360" y2="250" style="stroke:var(--fig