('e2d52d12-7cc8-527a-afb2-20ab2a84856d', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Timing more oscillations in each measurement', 'C', true, 2),
('47c71260-013c-57a6-91ad-cca99e60785e', 'cc6001dc-ebc2-517e-a698-6b46afafcccd', 'Timing from the end of the swing instead of the centre', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('3e517679-d067-58ea-a303-718b27e16d83', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 7, 7, 'What is the period of an oscillation?', NULL, 1, 'multiple_choice'::answer_type, 'The time taken for one complete oscillation', NULL, false, NULL, false, NULL, 'T is the time for one full cycle; frequency f = 1/T is the number of cycles per second. Mark scheme (1 mark). B1: C (The time taken for one complete oscillation).', 1, NULL, NULL),
('1c1acbe1-f139-5cf4-90ab-3c0e86a3519d', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 8, 8, 'What is the unit of frequency?', NULL, 1, 'multiple_choice'::answer_type, 'hertz (Hz), equal to s⁻¹', NULL, false, NULL, false, NULL, 'Frequency is the number of oscillations per unit time: 1 Hz = 1 oscillation per second = 1 s⁻¹. Mark scheme (1 mark). B1: A (hertz (Hz), equal to s⁻¹).', 1, NULL, NULL),
('e26c98a3-ea86-56e4-833f-a23f9b849396', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 9, 9, 'A boat bobs on waves with a frequency of 0.25 Hz. Calculate the period.', NULL, 1, 'numeric'::answer_type, '4', 's', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 0.25 = 4.0 s. Mark scheme (1 mark). A1: T = 4.0 s.', 1, NULL, NULL),
('188230a4-36dc-5e99-9d01-7c67a6ae0343', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 10, 10, 'A slow-motion video shows a hummingbird''s wing completing each beat in 0.040 s. What is the angular frequency of the beat?', NULL, 1, 'numeric'::answer_type, '157.1', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2π/T = 2π ÷ 0.040 = 157 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T. A1: ω = 157 rad s⁻¹.', 2, NULL, NULL),
('d6cbf2d5-7295-5501-89d0-afe4bb821255', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 11, 11, 'What is meant by displacement in an oscillation?', NULL, 1, 'multiple_choice'::answer_type, 'The distance from the equilibrium position in a stated direction', NULL, false, NULL, false, NULL, 'Displacement x is measured from the equilibrium position and has a sign (direction). Its maximum value is the amplitude. Mark scheme (1 mark). B1: D (The distance from the equilibrium position in a stated direction).', 1, NULL, NULL),
('5e56b142-9daf-56e3-89da-d292409becc4', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 12, 12, 'Two pendulums swing with the same frequency. One reaches its maximum displacement a quarter of a period after the other. What is their phase difference?', NULL, 1, 'multiple_choice'::answer_type, 'π/2 rad (90°)', NULL, false, NULL, false, NULL, 'A full period corresponds to 2π rad, so a quarter period corresponds to 2π/4 = π/2 rad. Mark scheme (1 mark). B1: B (π/2 rad (90°)).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgb267ef0a-t fgb267ef0a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb267ef0a-t">Two pendulums</title><desc id="fgb267ef0a-d">Displacement against time for two pendulums of the same frequency: B (dashed) reaches each maximum a quarter of a period after A.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="68.8" y1="34" x2="68.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="148.8" x2="382" y2="148.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="148.8" x2="388" y2="148.8" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:curre