('32618998-2b91-5534-94e9-11dc733fcbd8', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 22, 22, 'Two waves arriving at a point are 0.30 of a cycle out of step. Calculate their phase difference in degrees.', NULL, 1, 'numeric'::answer_type, '108', '°', false, NULL, false, NULL, 'phase difference = 0.30 × 360 = 108°. Mark scheme (2 marks). C1: fraction × 360°. A1: φ = 108°.', 2, NULL, NULL),
('b1a27053-5a07-546c-8f20-65c0a27faf52', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', '4e983cb3-2f8d-40bb-bc3f-1575fb3c3a35', 'a-level', '18.3', '9702 coursebook 18.3 · Describing oscillations', 23, 23, 'Two pendulums each of period 1.60 s are released 0.20 s apart. Calculate their phase difference in radians and as a fraction of a cycle. Give the phase difference in radians.', NULL, 2, 'numeric'::answer_type, '0.7854', 'rad', false, NULL, false, NULL, 'Fraction of cycle = 0.20 ÷ 1.60 = 0.125. φ = 0.125 × 2π = 0.785 rad (π/4). Mark scheme (3 marks). C1: fraction = Δt/T. C1: × 2π. A1: φ = 0.785 rad.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg82116a6e-t fg82116a6e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg82116a6e-t">Two pendulums</title><desc id="fg82116a6e-d">Displacement against time for two pendulums of period 1.60 s, each released from its maximum displacement: B (dashed) is released 0.20 s after A.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="68.8" y1="34" x2="68.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="113.5" y1="34" x2="113.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="158.2" y1="34" x2="158.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="247.8" y1="34" x2="247.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><lin