('7bc4065b-1827-5042-90ed-dc3d00114bba', 'e44fcb3d-89fd-5e87-967d-2b68f3ab4ed2', 'a = −ωx²', 'D', false, 3),
('96b1451b-80ad-5303-b548-f0aad0093459', '1a251721-d606-5ae1-8b9b-8735b7f33354', 'The acceleration is always directed towards the equilibrium position', 'A', true, 0),
('88891ff7-b1ac-517a-b3d3-83d605d4ec9c', '1a251721-d606-5ae1-8b9b-8735b7f33354', 'The acceleration is always negative', 'B', false, 1),
('b510c20d-8e2b-542d-b406-d10c8cca421a', '1a251721-d606-5ae1-8b9b-8735b7f33354', 'The object slows down all the time', 'C', false, 2),
('3fb30ef7-9e0a-549d-831c-eb8a1bf57c44', '1a251721-d606-5ae1-8b9b-8735b7f33354', 'The displacement is always negative', 'D', false, 3),
('412f23e7-62df-574a-9202-8efc9c9efde6', '9f6f86c6-0847-5061-9f60-fde20cd532f3', 'At maximum displacement', 'A', false, 0),
('8f9b3836-e1d4-5c65-9625-f84e01e3879c', '9f6f86c6-0847-5061-9f60-fde20cd532f3', 'Halfway between equilibrium and maximum displacement', 'B', false, 1),
('c2f551ba-ae6d-57b4-bb9a-895dd1c951d8', '9f6f86c6-0847-5061-9f60-fde20cd532f3', 'It is the same everywhere', 'C', false, 2),
('a885b144-5f16-5ebf-bb9d-481fd14d67a4', '9f6f86c6-0847-5061-9f60-fde20cd532f3', 'At the equilibrium position', 'D', true, 3),
('9afbe197-0ed6-5bbd-aa14-fb68635c6680', '090e931f-1d8e-5d7b-8d25-79d9a006d817', 'A ball bouncing on a hard floor', 'A', false, 0),
('42e8971b-2f0b-5707-87d9-6583c90b79ef', '090e931f-1d8e-5d7b-8d25-79d9a006d817', 'A mass bouncing gently on a spring', 'B', true, 1),
('e330606f-5c02-5905-99ec-235cf281b8fd', '090e931f-1d8e-5d7b-8d25-79d9a006d817', 'A car going round a roundabout', 'C', false, 2),
('2246a965-1286-5066-a84b-7448c661a1dc', '090e931f-1d8e-5d7b-8d25-79d9a006d817', 'A ball rolling down a slope', 'D', false, 3),
('a462de9b-48a0-5279-8a9b-2b71de74aee5', 'b7cef488-68db-504f-8b03-49ce3201eb22', 'The speed is maximum and the acceleration is zero', 'A', false, 0),
('bc9479ca-e0ac-5ef5-9c31-4bf949e1ab41', 'b7cef488-68db-504f-8b03-49ce3201eb22', 'Both speed and acceleration are zero', 'B', false, 1),
('3e505c5b-97fd-5f6f-a273-2d391331e4d2', 'b7cef488-68db-504f-8b03-49ce3201eb22', 'The speed is zero and the acceleration is maximum', 'C', true, 2),
