('3e7c4c9d-c8e3-5714-9f02-79dacc0ea131', 'c5d28598-342b-520d-a0ea-7bf5bb239bc1', 'It quadruples', 'A', false, 0),
('b0f6b5d3-ef0e-5482-bbe1-edb4911057bf', 'c5d28598-342b-520d-a0ea-7bf5bb239bc1', 'It stays the same', 'B', false, 1),
('39850507-87e6-5da1-b81b-6930b9d21c22', 'c5d28598-342b-520d-a0ea-7bf5bb239bc1', 'It halves', 'C', false, 2),
('8b757de1-e389-55d9-9196-2871fb77b339', 'c5d28598-342b-520d-a0ea-7bf5bb239bc1', 'It doubles', 'D', true, 3),
