('fd5ff032-bc41-59d7-ba68-cd87e5c56e61', 'd291110b-42e2-568b-88aa-df1ded96b7ad', 'Anywhere, because acceleration is always zero', 'C', false, 2),
('43d9cf30-dabc-591f-a789-8fb1e620f320', 'd291110b-42e2-568b-88aa-df1ded96b7ad', 'At half the amplitude', 'D', false, 3),
('c209b956-2187-549c-a675-44f96d81a85d', '56ca3200-6d7d-5fae-b062-19a4c74f4fee', 'A straight line through the origin with positive gradient', 'A', false, 0),
('b928fe75-6248-5ba8-a8b5-ea82d577a08c', '56ca3200-6d7d-5fae-b062-19a4c74f4fee', 'A horizontal line', 'B', false, 1),
('7fae0fc3-51fb-531e-8839-3469a0b668b9', '56ca3200-6d7d-5fae-b062-19a4c74f4fee', 'A straight line through the origin with negative gradient', 'C', true, 2),
('8bc237c7-9f9f-5448-b29b-b5f1950d01c3', '56ca3200-6d7d-5fae-b062-19a4c74f4fee', 'A parabola', 'D', false, 3),
('6575ddb0-2af8-5aeb-a428-bfe1da285ccd', '3139979a-98e8-539e-8c56-ae9b1103b2ac', 'The acceleration changes all the time: it is proportional to the displacement, so it varies from zero to its maximum value', 'A', true, 0),
('e7c9e325-f0cd-5a59-a429-1375d3075d56', '3139979a-98e8-539e-8c56-ae9b1103b2ac', 'Nothing is wrong', 'B', false, 1),
('1744f766-4539-5683-88b5-d3e2fad443ff', '3139979a-98e8-539e-8c56-ae9b1103b2ac', 'The acceleration is always zero in s.h.m.', 'C', false, 2),
('2db5cba8-11a0-55a9-807e-4f83a923f36b', '3139979a-98e8-539e-8c56-ae9b1103b2ac', 'Only the speed is constant', 'D', false, 3),
('66b7e61c-8781-548f-88f7-2997003799cb', '75e15945-e191-58fa-9df8-8a7af6db4cc9', 'Half the amplitude', 'A', false, 0),
('3462c8f9-3ec6-597d-9de1-cec666279b2e', '75e15945-e191-58fa-9df8-8a7af6db4cc9', 'One quarter of the amplitude', 'B', false, 1),
('c84a25bb-21b0-51b0-9668-a86c849fe4cb', '75e15945-e191-58fa-9df8-8a7af6db4cc9', '√2/2 of the amplitude', 'C', false, 2),
('3eac170d-55a2-51b5-8da1-55b7743d4270', '75e15945-e191-58fa-9df8-8a7af6db4cc9', '√3/2 of the amplitude, about 0.87x₀', 'D', true, 3),
