INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('d094a8e2-73b1-5bdf-bbd7-cf83fd384499', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 7, 7, 'The displacement–time graph of an s.h.m. is a sine curve. What is the shape of its velocity–time graph?', NULL, 1, 'multiple_choice'::answer_type, 'A cosine curve: the same shape shifted by a quarter of a period', NULL, false, NULL, false, NULL, 'v is the gradient of the x–t graph. The gradient of sin ωt is ω cos ωt: a sinusoid π/2 ahead. Mark scheme (1 mark). B1: C (A cosine curve: the same shape shifted by a quarter of a period).', 1, NULL, NULL),
('d43f8c8f-6aa6-5c4e-bdc5-e129d3cc0bef', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 8, 8, 'How is the acceleration–time graph of s.h.m. related to its displacement–time graph?', NULL, 1, 'multiple_choice'::answer_type, 'It is the displacement graph inverted (in antiphase) and scaled by ω²', NULL, false, NULL, false, NULL, 'a = −ω²x: same shape as x, flipped upside down. Mark scheme (1 mark). B1: A (It is the displacement graph inverted (in antiphase) and scaled by ω²).', 1, NULL, NULL),
('7c567c02-9d2f-51ed-9144-d7adb4f1b74a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 9, 9, 'On a displacement–time graph of s.h.m., where is the velocity zero?', NULL, 1, 'multiple_choice'::answer_type, 'At the peaks and troughs', NULL, false, NULL, false, NULL, 'The gradient is zero at the peaks and troughs, where the object momentarily stops. Mark scheme (1 mark). B1: D (At the peaks and troughs).', 1, NULL, NULL),
('6b61f8bd-8e04-5997-b525-3eb0179d4a69', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 10, 10, 'On a velocity–time graph of s.h.m., what does the gradient represent?', NULL, 1, 'multiple_choice'::answer_type, 'The acceleration', NULL, false, NULL, false, NULL, 'Acceleration is the rate of change of velocity: the gradient of v–t. Mark scheme (1 mark). B1: B (The acceleration).', 1, NULL, NULL),
('80d8a824-1eb7-577c-bb82-dfc63fc5b995', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 11, 11, 'A displacement–time graph of s.h.m. has peaks at +6.0 cm and the time between successive peaks is 0.80 s. Calculate the maximum speed.', NULL, 1, 'numeric'::answer_type, '0.4712', 'm s⁻¹', false, NULL, false, NULL, 'v_max = ωx₀ = (2π ÷ 0.80) × 0.060 = 0.471 m s⁻¹. Mark scheme (2 marks). C1: ω = 2π/T, v_max = ωx₀. A1: v_max = 0.471 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg2a87c445-t fg2a87c445-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2a87c445-t">Displacement against time</title><desc id="fg2a87c445-d">Displacement–time graph of s.h.m. with peaks at +6.0 cm, 0.80 s apart.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="117.6" y1="34" x2="117.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205.7" y1="34" x2="205.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="293.9" y1="34" x2="293.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="227.1" x2="382" y2="227.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="182.6" x2="382" y2="182.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;s