('a66928a7-989c-5644-8eae-8e9509536e7a', '70f5e4f8-856a-42b5-a2db-b89d66bae49a', 'cecb7488-b8aa-4ae3-af2a-d77c04d03414', 'a-level', '18.5', '9702 coursebook 18.5 · Representing s.h.m. graphically', 21, 21, 'Which feature of a displacement–time graph gives the amplitude?', NULL, 1, 'multiple_choice'::answer_type, 'The height of a peak above the equilibrium line', NULL, false, NULL, false, NULL, 'Amplitude is the maximum displacement from equilibrium: the peak height. Mark scheme (1 mark). B1: A (The height of a peak above the equilibrium line).', 1, NULL, NULL),
